"use client";

import {
    Wallet,
    ArrowUpRight,
    ArrowDownCircle,
    Download,
    Clock,
    CheckCircle2,
    Search,
    TrendingUp,
    CreditCard,
    Banknote,
    Calendar,
    Filter
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { useSimulation } from "@/components/SimulationProvider";

const mockTransactions = [
    { id: 1, type: 'Comissão', value: 45.00, client: 'Lutero E Associados', date: '2026-03-01 10:30', status: 'Liquidado' },
    { id: 2, type: 'Saque', value: -500.00, client: 'Transferência Bancária', date: '2026-02-28 15:45', status: 'Processando' },
    { id: 3, type: 'Comissão', value: 90.00, client: 'Montenegro E Duarte', date: '2026-02-28 09:12', status: 'Liquidado' },
];

export default function FinanceiroPage() {
    const { currentUser } = useSimulation();

    return (
        <div className="p-4 lg:p-8 space-y-8">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-black mb-1">Financeiro</h1>
                    <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Gestão de Ganhos e Transferências</p>
                </div>
                <button className="bg-primary text-white px-6 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 shadow-lg shadow-primary/20 hover:scale-[1.02] transition-all self-start md:self-auto">
                    <ArrowDownCircle size={16} />
                    Solicitar Saque
                </button>
            </div>

            {/* Balance Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm overflow-hidden relative group">
                    <div className="relative z-10">
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Saldo Disponível</p>
                        <h4 className="text-3xl font-black mb-4">R$ 1.250,00</h4>
                        <div className="flex items-center gap-2 text-xs font-bold text-emerald-500">
                            <TrendingUp size={14} />
                            <span>+R$ 450,00 esta semana</span>
                        </div>
                    </div>
                    <Wallet className="absolute -bottom-4 -right-4 size-32 text-slate-50 dark:text-slate-700/50 group-hover:text-primary/5 transition-colors -z-0" />
                </div>

                <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">A Liberar (Previsão)</p>
                    <h4 className="text-3xl font-black mb-4 text-slate-400">R$ 380,00</h4>
                    <div className="flex items-center gap-2 text-xs font-bold text-slate-400">
                        <Clock size={14} />
                        <span>Ciclo de 15 dias</span>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Total Sacado</p>
                    <h4 className="text-3xl font-black mb-4">R$ 4.720,00</h4>
                    <div className="flex items-center gap-2 text-xs font-bold text-indigo-500">
                        <CheckCircle2 size={14} />
                        <span>Tudo em dia</span>
                    </div>
                </div>
            </div>

            {/* Transaction History */}
            <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <h3 className="text-lg font-bold">Extrato Detalhado</h3>
                    <button className="flex items-center gap-2 text-xs font-bold text-primary hover:underline">
                        <Download size={14} />
                        Exportar CSV
                    </button>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50/50 dark:bg-white/5 border-b border-slate-100 dark:border-slate-800">
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Tipo / Descrição</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Data e Hora</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Status</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-right">Valor</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                            {mockTransactions.map((tx) => (
                                <tr key={tx.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-900/50 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <div className={cn(
                                                "size-9 rounded-xl flex items-center justify-center",
                                                tx.value > 0 ? "bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20" : "bg-rose-50 text-rose-600 dark:bg-rose-900/20"
                                            )}>
                                                {tx.value > 0 ? <Banknote size={18} /> : <CreditCard size={18} />}
                                            </div>
                                            <div>
                                                <p className="text-sm font-bold text-slate-900 dark:text-white">{tx.type}</p>
                                                <p className="text-[10px] text-slate-500 font-medium">{tx.client}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2 text-slate-500">
                                            <Calendar size={14} />
                                            <span className="text-xs font-medium">{tx.date}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={cn(
                                            "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold ring-1 ring-inset",
                                            tx.status === 'Liquidado' ? "bg-emerald-50 text-emerald-700 ring-emerald-600/20 dark:bg-emerald-400/10 dark:text-emerald-400" :
                                                "bg-amber-50 text-amber-700 ring-amber-600/20 dark:bg-amber-400/10 dark:text-amber-400"
                                        )}>
                                            {tx.status}
                                        </span>
                                    </td>
                                    <td className={cn(
                                        "px-6 py-4 text-right text-sm font-black",
                                        tx.value > 0 ? "text-emerald-500" : "text-rose-500"
                                    )}>
                                        {tx.value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}
